import{_ as l,o as a,c as e,ag as o}from"./chunks/framework.C9sp7nFj.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ChangeLog.md","filePath":"ChangeLog.md","lastUpdated":1778862643000}'),t={name:"ChangeLog.md"};function r(n,i,h,s,d,S){return a(),e("div",null,[...i[0]||(i[0]=[o('<h3 id="_2025-5-26-v1-19" tabindex="-1">2025.5.26 - V1.19 <a class="header-anchor" href="#_2025-5-26-v1-19" aria-label="Permalink to &quot;2025.5.26 - V1.19&quot;">​</a></h3><ol><li>新增消息提示指令列表。</li><li>新增消息提示指令 DialogPanel、DialogPanelInt、DialogPanelReal。</li><li>新增 CTV 类型变量，以及在 MovJ、MovL、MovC 中增加 CTV 参数。</li><li>在 IO 指令列表里新增 GetSimAIToInt 指令。</li><li>在位置运算指令列表里新增 CalcPosDist 指令。</li><li>在飞拍指令中新增了 RecordLatchPos 指令，SetLatchPos 指令新增了记录点索引参数，默认缺省。</li><li>在设置指令列表中新增 GetAxisTorque 指令。</li><li>在“6.15 阵列指令”章节中新增“SetMatrixFourPoint”、“GetMatrixFourPoint”指令。</li><li>新增“3.24 Mc 通讯指令”。</li></ol><hr><h3 id="_2025-1-9-v1-18" tabindex="-1">2025.1.9 - V1.18 <a class="header-anchor" href="#_2025-1-9-v1-18" aria-label="Permalink to &quot;2025.1.9 - V1.18&quot;">​</a></h3><ol><li>中断指令列表中新增 ISleep 和 IWatch 指令，以及新增 ISignalDI 和 ISignalSimDI 指令的去重时间参数。</li><li>修改 SetMatrix 指令的行数和列数参数类型。</li><li>飞拍指令列表中新增 SetLatchPosAttr 和 SetLatchPosDyn 指令。</li></ol><hr><h3 id="_2024-7-1-v1-17" tabindex="-1">2024.7.1 - V1.17 <a class="header-anchor" href="#_2024-7-1-v1-17" aria-label="Permalink to &quot;2024.7.1 - V1.17&quot;">​</a></h3><ol><li>修正中断指令中 ExitCycle 的指令描述。</li><li>新增飞拍指令列表。</li><li>修改字符串指令列表中对 fmod、floor 函数的描述。</li></ol><hr><h3 id="_2024-1-31-v1-16" tabindex="-1">2024.1.31 - V1.16 <a class="header-anchor" href="#_2024-1-31-v1-16" aria-label="Permalink to &quot;2024.1.31 - V1.16&quot;">​</a></h3><ol><li>在系统数据类型中新增 VIBRATIONPARAM、SYNCID 变量。</li><li>在基本数据类型中新增 StringOneArray 变量。</li><li>在变量数据类型中，为除 RealOneArray、IntOneArray、BoolOneArray、StringOneArray、SPEED、ZONE、APOSARRAY、CPOSARRAY 以外的所有变量新增变量注释参数。</li><li>在摆动数据类型中更新 WEAVE 变量的参数说明。</li><li>新增主从运动指令列表。</li><li>在设置指令列表中删除 RefRobotAxis 指令。</li><li>在传送带跟随指令列表中更新 WaitWObj 指令、MovJSyncQuit 指令、MovLSyncQuit 指令、ResetWObjBuf 指令的参数说明。</li><li>在运动指令列表中更新 MovArch 指令、MovLArch 指令的参数说明，新增 MovJOffsetC 指令、MovLOffsetC 指令的参数说明。</li><li>在字符串指令列表中新增 TranStrToStr 指令，同时补充 sub、removeStr 的指令说明。</li><li>在 IO 指令列表和设置指令列表中，相关指令的参数值支持常量和变量。</li><li>在设置指令列表中更新 SetMotionMode 指令的参数说明，新增 SetVibrationParam 指令、AutoTune 指令的参数说明。</li><li>除点位数组变量外，其余变量支持变量复制和粘贴操作。</li></ol><hr><h3 id="_2023-8-14-v1-15" tabindex="-1">2023.8.14 - V1.15 <a class="header-anchor" href="#_2023-8-14-v1-15" aria-label="Permalink to &quot;2023.8.14 - V1.15&quot;">​</a></h3><ol><li>在运动指令列表中新增了 MovJHand 指令。</li><li>在中断指令列表中更新了 ExitCycle 指令说明。</li></ol><hr><h3 id="_2023-7-14-v1-14" tabindex="-1">2023.7.14 - V1.14 <a class="header-anchor" href="#_2023-7-14-v1-14" aria-label="Permalink to &quot;2023.7.14 - V1.14&quot;">​</a></h3><ol><li>修改了 SetRtInfo、SetRtToErr、SetRtWarning 的信息与编号参数说明。</li><li>将原 SetOriMode 变更为 SetCircMode，更新其参数说明。同时对新的 SetOriMode 进行描述。</li><li>在位置运算指令列表中新增了 PosOffset、AxisLock 指令。</li><li>修改了区域变量的参数说明。</li><li>在控制指令列表中新增了 SWITCH、CASE、BREAK、DEFAULT 指令。</li><li>在设置指令列表中新增 SetSCARAMode 指令。</li></ol><hr><h3 id="_2023-3-16-v1-13" tabindex="-1">2023.3.16 - V1.13 <a class="header-anchor" href="#_2023-3-16-v1-13" aria-label="Permalink to &quot;2023.3.16 - V1.13&quot;">​</a></h3><ol><li>新增 APOSARRAY、CPOSARRAY、INTERRUPT。</li><li>修改了 OnDistance 指令中的距离与时间参数说明。</li><li>修改了 OnParameter 指令中的时间参数说明。</li><li>修改了 MovJSearch、MovLSearch 指令中的返回值参数说明，同时新增了 SearchP、Goto 参数。</li><li>在运动指令列表中新增 MovJOffset、MovLArch 指令。</li><li>在设置指令列表中新增 SetOriMode、GetRobotIsMoving、SetColliAutoTune、SetColliParam 指令。</li><li>在位置运算指令列表中新增 CalPosOffset 指令。</li><li>在区域指令列表中新增 AreaConnectIO、AreaDisConnectIO、PolyhedronAreaConnectIO、PolyhedronAreaDisConnectIO 指令。</li><li>新增中断指令列表。</li><li>新增负载在线辨识指令列表。</li><li>在系统变量中新增 INTERRUPT、COLLIPARAM 参数。</li></ol><hr><h3 id="_2022-10-28-v1-12" tabindex="-1">2022.10.28 - V1.12 <a class="header-anchor" href="#_2022-10-28-v1-12" aria-label="Permalink to &quot;2022.10.28 - V1.12&quot;">​</a></h3><ol><li>修改了 SocketReadReal、SocketReadInt 指令中接收数据的格式说明，以及 SocketSendStr 指令中的参数说明。</li><li>在 Socket 指令集中新增了 SocketResetBuf 指令。</li><li>在 AREA 变量中新增了 isFlangeEnd 参数。</li><li>修正了 RUN 指令的说明。</li><li>修正了 WaitDI8421、WaitSimDI8421 指令参数说明顺序。</li></ol><hr><h3 id="_2022-7-18-v1-11" tabindex="-1">2022.7.18 - V1.11 <a class="header-anchor" href="#_2022-7-18-v1-11" aria-label="Permalink to &quot;2022.7.18 - V1.11&quot;">​</a></h3><ol><li>在 MovArch 指令中新增 H2 参数，并修改了部分指令参数说明。</li><li>传送带跟随指令中新增 SimConveyorOn、SimConveyorOff、ReceiveWObj、ResetWObjBuf 指令。</li></ol><hr><h3 id="_2022-4-13-v1-10" tabindex="-1">2022.4.13 - V1.10 <a class="header-anchor" href="#_2022-4-13-v1-10" aria-label="Permalink to &quot;2022.4.13 - V1.10&quot;">​</a></h3><ol><li>在位置运算指令列表中新增 ToolOffset、UserOffset 指令。</li></ol><hr><h3 id="_2022-1-6-v1-9" tabindex="-1">2022.1.6 - V1.9 <a class="header-anchor" href="#_2022-1-6-v1-9" aria-label="Permalink to &quot;2022.1.6 - V1.9&quot;">​</a></h3><ol><li>修改 Wait、WaitCondition、WaitDI、WaitDI8421、WaitAI、WaitSimDI、WaitSimDI8421、WaitSimAI 等指令中时间参数的类型说明，修改 SetOverride 指令中速度倍率参数的类型说明。</li><li>新建字符串指令列表，将赋值指令与流程控制指令中的字符串函数移至其中，并新增 findEnd、format、getAt、left、right、reverse、strcmp、trimLeft、trimRight、IToStr、RToStr、StrToI、StrToR、APosToStr、CPosToStr、TranStrToInt、TranStrToReal、TranStrToApos、TranStrToCpos 指令。同时移除赋值指令与流程控制指令中的字符串函数。</li><li>在传送带跟随指令列表中新增 WaitConvDis 指令。</li><li>在设置指令列表中新增 SetRestorePC、SetAxisVibraBLevel 指令。</li><li>将 WEAVE 变量中的 Amp 属性变更为 Amp_L、Amp_R，StopTime 属性变更为 StopTime_L、StopTime_C、StopTime_R。</li><li>在运动指令列表中增加 MovCircle、MovCircleW 指令。</li><li>在 PLC 数据类型中新增 PLCBOOL、PLCINT、PLCDINT 变量。</li><li>新增 ModbusTcp 指令列表。</li></ol><hr><h3 id="_2021-10-15-v1-8" tabindex="-1">2021.10.15 - V1.8 <a class="header-anchor" href="#_2021-10-15-v1-8" aria-label="Permalink to &quot;2021.10.15 - V1.8&quot;">​</a></h3><ol><li>完善系统关键字 (词)。</li><li>新增区域数据类型的多边体区域变量。</li><li>修改指令 MovL、MovC、MovLRel、MovLW、MovCW 指令中的坐标系参数。</li><li>新增 PolyhedronAreaActivate、PolyhedronAreaDeactivate 指令。</li></ol><hr><h3 id="_2021-7-26-v1-7" tabindex="-1">2021.7.26 - V1.7 <a class="header-anchor" href="#_2021-7-26-v1-7" aria-label="Permalink to &quot;2021.7.26 - V1.7&quot;">​</a></h3><ol><li>MovL、MovC、MovLRel、MovLW、MovCW 指令新增参数：是否受全局速度倍率影响。</li><li>新增 MovLOffset、SetSingularPass、SetColliEnable、SetAxisColliParam、SetMatrix、GetMatrix、SocketSendReal、SocketSendInt、SetPositioner、SetBlendParam 指令。</li><li>修改指令名 GetOverRide 为 GetCurOverRide。</li></ol><hr><h3 id="_2021-5-24-v1-6" tabindex="-1">2021.5.24 - V1.6 <a class="header-anchor" href="#_2021-5-24-v1-6" aria-label="Permalink to &quot;2021.5.24 - V1.6&quot;">​</a></h3><ol><li>在 MovLSync 指令中新增了两个 Goto 属性变量以及抬升高度。</li><li>新增 LsScale、LsThresh 变量。</li><li>在设置指令中新增 AutoGainEnable、AutoGainDisable 指令。</li></ol><hr><h3 id="_2021-2-8-v1-5" tabindex="-1">2021.2.8 - V1.5 <a class="header-anchor" href="#_2021-2-8-v1-5" aria-label="Permalink to &quot;2021.2.8 - V1.5&quot;">​</a></h3><ol><li>新增 MovLSync、MovJSyncQuit、MovLSyncQuit、WaitWObj、SetTargetPos 指令，并新建一个传送带跟随指令列表来存储。</li><li>新增 SYNCOORD 变量。</li><li>在 WaitCondition、WaitDI、WaitDI8421、WaitAI、WaitSimDI、WaitSimDI8421、WaitSimAI 这些时间等待指令中新增了 Goto 属性变量。</li><li>在区域变量中新增 initActivate，enInPut，enInHigh 三个属性。</li><li>新增 ELSIF 指令。</li></ol><hr><h3 id="_2020-7-13-v1-4" tabindex="-1">2020.7.13 - V1.4 <a class="header-anchor" href="#_2020-7-13-v1-4" aria-label="Permalink to &quot;2020.7.13 - V1.4&quot;">​</a></h3><ol><li>新增 SetExternalTCP 指令。</li><li>修改 MovL、MovC 指令中 Coord 属性说明。</li><li>WAVE 变量新增 Type 属性。</li><li>新增 EXTTCP 变量类型。</li><li>其他修改。</li></ol><hr><h3 id="_2019-12-31-v1-3" tabindex="-1">2019.12.31 - V1.3 <a class="header-anchor" href="#_2019-12-31-v1-3" aria-label="Permalink to &quot;2019.12.31 - V1.3&quot;">​</a></h3><ol><li>移除 EMovL, EMovC 指令说明。</li><li>除了 MovJRel，MovLRel 两条指令添加了 PAYLOAD 属性外，其他所有的运动指令中均添加了 TOOL, USERCOOR,PAYLOAD 属性变量，对这些添加的属性变量进行说明。</li><li>修改 SetPayload 指令说明。</li><li>新增 SetRtInfo, SetRtWarning 指令说明。</li><li>新增 PAYLOAD 变量说明。</li><li>其他修改。</li></ol><hr><h3 id="_2019-07-22-v1-2" tabindex="-1">2019.07.22 - V1.2 <a class="header-anchor" href="#_2019-07-22-v1-2" aria-label="Permalink to &quot;2019.07.22 - V1.2&quot;">​</a></h3><ol><li>新增 SetMotionMode 与 GetCurOverRide 指令说明。</li><li>修改码垛指令参数说明。</li></ol><hr><h3 id="_2019-04-22-v1-1" tabindex="-1">2019.04.22 - V1.1 <a class="header-anchor" href="#_2019-04-22-v1-1" aria-label="Permalink to &quot;2019.04.22 - V1.1&quot;">​</a></h3><ol><li>修正版本。</li></ol><hr><h3 id="_2019-04-17-v1-0" tabindex="-1">2019.04.17 - V1.0 <a class="header-anchor" href="#_2019-04-17-v1-0" aria-label="Permalink to &quot;2019.04.17 - V1.0&quot;">​</a></h3><ol><li>初次发布。</li></ol>',59)])])}const A=l(t,[["render",r]]);export{v as __pageData,A as default};
